function tilePop(weights, tolerance) {
  const n = weights.length;
  const width = n + 2;
  const clear = new Uint8Array(width * width);
  const best = new Int32Array(width * width);
  const at = (i, j) => i * width + (j + 1);
  const sum = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) sum[i + 1] = sum[i] + weights[i];
  for (let i = 0; i <= n; i++) clear[at(i, i - 1)] = 1;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      let canClear = 0;
      let most = best[at(i + 1, j)];
      for (let k = i + 1; k <= j; k += 2) {
        if (Math.abs(weights[i] - weights[k]) > tolerance) continue;
        if (clear[at(i + 1, k - 1)] === 0) continue;
        if (clear[at(k + 1, j)] === 1) canClear = 1;
        const candidate = sum[k + 1] - sum[i] + best[at(k + 1, j)];
        if (candidate > most) most = candidate;
      }
      clear[at(i, j)] = canClear;
      best[at(i, j)] = most;
    }
  }
  return best[at(0, n - 1)];
}
